#include <Arduino.h>
#include <HWCDC.h> // USB通信を強制的に生かすためのライブラリ

// USB通信を制御するインスタンスを作成
HWCDC USBSerial;
#define TARGET_PIN 2

void setup() {
  // 起動時にUSB通信の初期化を強制実行（ループ音を止めるキモです）
  USBSerial.begin(115200);

  pinMode(TARGET_PIN, OUTPUT);
}

void loop() {
  digitalWrite(TARGET_PIN, HIGH);
  delay(500);

  digitalWrite(TARGET_PIN, LOW);
  delay(500);
}
